public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) return false;
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq[r]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) return false;
    // If k is even, check remainder k/2
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) return false;
    }
    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) continue; // already handled k even case
        if (freq[r] != freq[k - r]) return false;
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] e : edges) {
        int u = e[0], v = e[1];
        graph[u].add(v);
        graph[v].add(u);
    }
    int[] time = new int[1];
    dfs(0, -1, graph, hasApple, time);
    return time[0];
}

private boolean dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple, int[] time) {
    boolean hasAppleInSubtree = hasApple[node];
    for (int child : graph[node]) {
        if (child == parent) continue;
        boolean childHasApple = dfs(child, node, graph, hasApple, time);
        if (childHasApple) {
            time[0] += 2; // go to child and back
            hasAppleInSubtree = true;
        }
    }
    return hasAppleInSubtree;
}

public String sortString(String s) {
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder sb = new StringBuilder();
    int remaining = s.length();
    while (remaining > 0) {
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    // dp[k] holds all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        for (int size = n - 1; size >= 0; size--) {
            if (!dp[size].isEmpty()) {
                for (int s : dp[size]) {
                    dp[size + 1].add(s + num);
                }
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int fromPrev = dp[i - 1] + cost[i - 1];
        int fromPrevPrev = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(fromPrev, fromPrevPrev);
    }
    return dp[n];
}

