public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxSoFar = nums[0];
    int minSoFar = nums[0];
    int currentMax = nums[0];
    int currentMin = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int num = nums[i];
        currentMax = Math.max(num, currentMax + num);
        maxSoFar = Math.max(maxSoFar, currentMax);
        currentMin = Math.min(num, currentMin + num);
        minSoFar = Math.min(minSoFar, currentMin);
    }
    return Math.max(maxSoFar, -minSoFar);
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int sz = fibs.size();
        int next = fibs.get(sz - 1) + fibs.get(sz - 2);
        if (next > k) break;
        fibs.add(next);
    }

    int count = 0;
    int remaining = k;
    // Greedy: subtract the largest Fibonacci number <= remaining
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fibs.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    java.util.Collections.reverse(large);
    int count = 0;
    for (int f : small) {
        count++;
        if (count == k) return f;
    }
    for (int f : large) {
        count++;
        if (count == k) return f;
    }
    return -1;
}

public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int n = stack.length();
        if (n > 0) {
            char top = stack.charAt(n - 1);
            if (Math.abs(c - top) == 32) { // same letter, opposite case
                stack.deleteCharAt(n - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int max = 0;
    Deque<State> stack = new ArrayDeque<>();
    stack.push(new State(0, 0, new HashSet<>()));
    while (!stack.isEmpty()) {
        State cur = stack.pop();
        int pos = cur.pos;
        int count = cur.count;
        Set<String> used = cur.used;
        if (pos == n) {
            if (count > max) max = count;
            continue;
        }
        for (int end = pos + 1; end <= n; end++) {
            String sub = s.substring(pos, end);
            if (!used.contains(sub)) {
                Set<String> newUsed = new HashSet<>(used);
                newUsed.add(sub);
                stack.push(new State(end, count + 1, newUsed));
            }
        }
    }
    return max;

    class State {
        int pos;
        int count;
        Set<String> used;
        State(int pos, int count, Set<String> used) {
            this.pos = pos;
            this.count = count;
            this.used = used;
        }
    }
}

