public static int addDigits(int num) {
    if (num == 0) {
        return 0;
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) return 0;
    int m = mat.length;
    int n = mat[0].length;
    int[][] h = new int[m][n];
    int[][] v = new int[m][n];
    int[][] d = new int[m][n];
    int[][] a = new int[m][n];
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                h[i][j] = (j > 0 ? h[i][j - 1] : 0) + 1;
                v[i][j] = (i > 0 ? v[i - 1][j] : 0) + 1;
                d[i][j] = (i > 0 && j > 0 ? d[i - 1][j - 1] : 0) + 1;
                a[i][j] = (i > 0 && j < n - 1 ? a[i - 1][j + 1] : 0) + 1;
                int cur = Math.max(Math.max(h[i][j], v[i][j]), Math.max(d[i][j], a[i][j]));
                if (cur > max) max = cur;
            }
        }
    }
    return max;
}

